    enonce: "احسب قيس محيط المضلّع إذا كان <span dir=\"ltr\" class=\"expr\">x = 4</span> علما أنّ <span dir=\"ltr\" class=\"expr\">P = 4 x + 11</span>",
    correction: [{"quoi":"نعوّض في العبارة","math":"<span dir=\"ltr\" class=\"expr\">P = 4 × 4 + 11</span>"},{"quoi":"نحسب الجداء","math":"<span dir=\"ltr\" class=\"expr\">4 × 4 = 16</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">16 + 11 = 27</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">P = 27</span>"}],
